"""Turn JSON event lines into per-user sessions."""

import json
import re
from datetime import datetime, timezone

_TIMESTAMP = re.compile(
    r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z",
    re.ASCII,
)


def _timestamp(value, line_number):
    if not _TIMESTAMP.fullmatch(value):
        raise ValueError(f"line {line_number}: at must be a real UTC whole-second timestamp")
    try:
        return datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    except ValueError:
        raise ValueError(
            f"line {line_number}: at must be a real UTC whole-second timestamp"
        ) from None


def rollup(events, idle_seconds):
    """Return deterministic per-user session summaries."""
    if type(idle_seconds) is not int or idle_seconds <= 0:
        raise ValueError("idle_seconds must be a positive integer")

    sessions = []
    active = {}
    previous = {}
    for line_number, raw in enumerate(events, 1):
        if not raw.strip():
            continue
        try:
            item = json.loads(raw)
        except (TypeError, json.JSONDecodeError):
            raise ValueError(
                f"line {line_number}: expected a JSON object with non-empty string user, at, and action"
            ) from None
        if not isinstance(item, dict) or any(
            not isinstance(item.get(name), str) or item[name] == ""
            for name in ("user", "at", "action")
        ):
            raise ValueError(
                f"line {line_number}: expected a JSON object with non-empty string user, at, and action"
            )

        user = item["user"]
        timestamp = _timestamp(item["at"], line_number)
        prior = previous.get(user)
        if prior is not None and timestamp < prior:
            raise ValueError(
                f"line {line_number}: timestamps for user {user} must be nondecreasing"
            )

        if prior is None or (timestamp - prior).total_seconds() >= idle_seconds:
            session = {
                "user": user,
                "started_at": item["at"],
                "ended_at": item["at"],
                "actions": {item["action"]: 1},
            }
            sessions.append(session)
            active[user] = session
        else:
            session = active[user]
            session["ended_at"] = item["at"]
            action = item["action"]
            session["actions"][action] = session["actions"].get(action, 0) + 1
        previous[user] = timestamp

    return sorted(sessions, key=lambda item: (item["started_at"], item["user"]))
